<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>LCC Intrusion Detection Simulator</title>
<style>
:root{font-family:Inter,'Segoe UI',Arial,sans-serif;color:#10203d;background:#f0f4fa}*{box-sizing:border-box}body{margin:0}button,select,input{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.shell{display:flex;min-height:100vh}.sidebar{width:250px;flex-shrink:0;background:#0d2141;color:#fff;padding:22px 12px}.brand{font-size:20px;font-weight:800;line-height:1.35;padding:0 12px 22px;border-bottom:1px solid #63728c}.nav{display:block;width:100%;text-align:left;background:none;color:#e9f4ff;border:0;border-radius:8px;padding:14px 15px;margin:7px 0;font-size:15px}.nav.active,.nav:hover{background:#008f91;color:#fff}.main{flex:1;min-width:0;padding:18px 24px 40px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.top h1{font-size:29px;margin:0}.muted{color:#64728a}.top p{margin:5px 0 16px}.tag{background:#e96b0d;color:white;padding:10px 14px;border-radius:8px;font-weight:800;font-size:12px}.status,.panel,.stat,.controls{background:white;border:1px solid #d2deeb;border-radius:11px;box-shadow:0 2px 7px #102d5310}.status{display:flex;justify-content:space-around;gap:12px;padding:16px;margin-bottom:16px;flex-wrap:wrap}.status b{color:#009b83}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.stat{padding:17px}.stat span{display:block;font-size:14px;font-weight:700}.stat strong{font-size:30px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 16px;margin:15px 0}.btn{background:white;border:1px solid #b4c6db;border-radius:7px;padding:10px 15px;color:#153354;font-weight:700}.btn.primary{background:#008b8b;color:white;border-color:#008b8b}.btn:hover:not(:disabled){filter:brightness(.94)}.controls select{border:1px solid #b4c6db;border-radius:7px;padding:8px}.progress{height:12px;background:#d9e2ef;border-radius:20px;flex:1;min-width:90px;overflow:hidden}.progress>div{height:100%;background:#00aaa3;width:0%;transition:width .2s}.two{display:grid;grid-template-columns:1fr 1.05fr;gap:15px;margin-bottom:15px}.panel{padding:16px;min-width:0}.panel h2{font-size:19px;margin:0 0 12px}.tablewrap{overflow:auto;max-height:365px}table{border-collapse:collapse;width:100%;font-size:13px}th{background:#e4ebf4;text-align:left;padding:9px;position:sticky;top:0}td{border-bottom:1px solid #d9e1ea;padding:8px}tr.selected{background:#d6f5f4;outline:1px solid #00aaa3}tbody tr[data-row]{cursor:pointer}tbody tr[data-row]:hover{background:#eaf7fa}.pill{display:inline-block;padding:5px 10px;border-radius:8px;font-weight:800;font-size:12px}.normal{background:#d2f5d8;color:#136222}.attack{background:#ffdadb;color:#ad101b}.unknown{background:#e9edf4;color:#56627a}.orange{background:#ec6c08;color:white;padding:9px;text-align:center;border-radius:6px;font-weight:800;margin-top:12px}.score{background:#fff4e5;padding:11px;border-radius:6px;margin-top:8px}.upload{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.notice{padding:12px;border-radius:8px;background:#fff3d6;border:1px solid #edcb80;margin-bottom:15px}.error{background:#ffebec;border-color:#ed9da3}.small{font-size:12px}.footer{margin:15px 0;color:#64728a;font-style:italic}.hidden{display:none!important}.right{margin-left:auto}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric{background:#edf5fc;border-radius:7px;padding:13px}.metric strong{display:block;font-size:22px}.section{display:none}.section.active{display:block}.empty{padding:20px;color:#62718a;text-align:center}.check{color:#008d75}.wide{grid-column:1/-1}@media(max-width:1050px){.stats{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}}@media(max-width:700px){.shell{display:block}.sidebar{width:100%;padding:10px}.brand{padding:8px}.nav{display:inline-block;width:auto;font-size:12px;padding:9px}.main{padding:12px}.top h1{font-size:23px}.grid4{grid-template-columns:repeat(2,1fr)}}

.capture-switch{display:flex;gap:10px;margin:0 0 16px;flex-wrap:wrap}.capture-switch button{border:1px solid #bdd1e2;background:white;color:#19345a;border-radius:9px;padding:12px 18px;font-weight:750}.capture-switch button[aria-pressed="true"]{background:#008f91;color:white;border-color:#008f91}.live-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(290px,1fr);gap:16px}.live-step{display:flex;gap:12px;align-items:flex-start;padding:13px 0;border-bottom:1px solid #e3eaf2}.live-num{flex-shrink:0;width:30px;height:30px;border-radius:50%;background:#dcebf8;color:#0d2141;display:grid;place-items:center;font-weight:800}.live-step strong{display:block}.live-step p{margin:4px 0;color:#64728a;font-size:13px}.live-badge{display:inline-block;border-radius:30px;background:#fff0d9;color:#8d4c00;padding:6px 10px;font-size:12px;font-weight:800}.code-inline{background:#eff4f9;padding:3px 6px;border-radius:4px}.live-note{background:#eef6fc;border:1px solid #b9d7e9;border-radius:9px;padding:13px;margin-top:14px;font-size:13px}.hidden-mode{display:none!important}@media(max-width:900px){.live-layout{grid-template-columns:1fr}}
</style></head><body><div class="shell"><aside class="sidebar"><div class="brand">◇ &nbsp;LCC Intrusion<br>&nbsp;&nbsp;&nbsp; Detection Simulator</div><nav aria-label="Dashboard navigation"><button class="nav" data-page="overview">⌂ &nbsp;Overview</button><button class="nav" data-page="dataset">▤ &nbsp;Dataset &amp; Validation</button><button class="nav active" data-page="simulation">▶ &nbsp;Simulation &amp; Features</button><button class="nav" data-page="evaluation">▥ &nbsp;Model Evaluation</button><button class="nav" data-page="ablation">⚗ &nbsp;Ablation Study</button></nav></aside><main class="main"><header class="top"><div><h1 id="pageTitle">Recorded Network Traffic Simulation</h1><p class="muted" id="sourceSubtitle">UNSW-NB15 dataset replay • Not live network capture</p></div><div class="tag" id="modeTag">DATASET REPLAY • REAL INFERENCE</div></header>
<div id="notice" class="notice {{ $bundleReady ? 'hidden' : '' }}">No inference bundle detected. Install the corrected E1–E5 model bundle to enable real predictions. The dashboard will not fabricate results.</div>
<section id="overview" class="section"><div class="panel"><h2>Overview</h2><p>Replay uploaded UNSW-NB15 network-flow CSVs through the trained E1–E5 models, inspect predictions and compare metrics. This application does not capture live traffic.</p><p id="overviewStatus" class="muted">No dataset analysed yet.</p><button class="btn primary" data-goto="dataset">Load dataset</button></div></section>
<section id="dataset" class="section"><div class="panel"><h2>Dataset &amp; Validation</h2><p class="muted">Select a CSV containing the nine required RF-selected features. An optional <code>label</code> column enables performance metrics. Maximum {{ $maxFiles }} files, {{ $maxFileMb }} MB per file.</p><div class="upload"><input id="fileInput" type="file" accept=".csv,text/csv" multiple><button id="analyseBtn" class="btn primary">Validate &amp; Run E1–E5</button><span id="uploadState" class="muted small">No file selected</span></div><p class="small muted">Features: sttl, ct_state_ttl, dload, rate, dmean, dttl, ackdat, sload, sbytes</p><div id="validationResult" class="notice hidden"></div></div></section>
<section id="simulation" class="section active">
<div class="capture-switch" role="group" aria-label="Traffic source"><button type="button" id="replayModeBtn" aria-pressed="true">▶ Dataset Replay</button><button type="button" id="liveModeBtn" aria-pressed="false">◉ Live Capture Setup</button></div>
<div id="liveModePanel" class="hidden-mode">
<div class="status"><span><b>◉</b> Capture service: <span class="live-badge">NOT CONFIGURED</span></span><span><b>▱</b> 9 UNSW-NB15 features required</span><span><b>⬡</b> E1–E5 inference bundle: {{ $bundleReady ? 'detected' : 'missing' }}</span></div>
<div class="live-layout"><div class="panel"><h2>Live Network Capture</h2><p class="muted">Prepare a local packet capture service for your own Windows PC or an authorized test network. This release does not yet include a packet capture backend; no live predictions are displayed.</p>
<div class="live-step"><span class="live-num">1</span><div><strong>Install packet capture dependencies</strong><p>Install Npcap and Python Scapy on the capture computer. Administrator privileges may be required.</p></div></div>
<div class="live-step"><span class="live-num">2</span><div><strong>Extract network-flow features</strong><p>Aggregate captured packets into flows and calculate sttl, ct_state_ttl, dload, rate, dmean, dttl, ackdat, sload, sbytes. Validate their definitions against UNSW-NB15.</p></div></div>
<div class="live-step"><span class="live-num">3</span><div><strong>Connect a validated local capture service</strong><p>Only after a compatible capture API is implemented should this dashboard show live Start / Stop controls and inference results.</p></div></div>
<div class="live-note"><strong>Research boundary:</strong> Live captured flows have no automatic ground-truth labels. Dataset Replay remains the valid source for E1–E5 benchmark evaluation.</div></div>
<div class="panel"><h2>Capture Readiness</h2><table><tbody><tr><th>Component</th><th>Status</th></tr><tr><td>Laravel UI</td><td>Ready</td></tr><tr><td>Python packet capture service</td><td>Not installed</td></tr><tr><td>Validated nine-feature extractor</td><td>Not connected</td></tr><tr><td>Live inference integration</td><td>Not connected</td></tr><tr><td>Saved E1–E5 bundle</td><td>{{ $bundleReady ? 'Detected' : 'Missing' }}</td></tr></tbody></table><div class="notice" style="margin-top:16px">Live capture cannot start until the capture service and feature extractor are installed and verified. This prevents misleading simulated alerts.</div><button class="btn primary" type="button" id="returnReplayBtn">Return to Dataset Replay</button></div></div></div>
<div class="panel" id="labelDemoPanel" style="margin-bottom:16px;border:2px solid #c7d9e8">
<h2>Normal vs Attack — Labeled Record Comparison</h2>
<p class="muted">Uses actual E1–E5 inference on uploaded labeled UNSW-NB15 records. Dataset labels are ground truth, not forced predictions. Select a sample below after analysis.</p>
<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0">
<button type="button" id="demoNormalBtn" disabled>Show labeled Normal (0)</button>
<button type="button" id="demoAttackBtn" disabled>Show labeled Attack (1)</button>
<button type="button" id="demoCompareBtn" disabled>Compare both</button>
</div>
<div id="demoNotice" class="muted" aria-live="polite">Upload and analyze a labeled CSV to activate this demonstration.</div>
<div class="tablewrap"><table><thead><tr><th>Dataset row</th><th>Actual</th><th>E1</th><th>E2</th><th>E3</th><th>E4</th><th>E5</th><th>E5 IF score</th><th>E5 outcome</th></tr></thead><tbody id="demoRows"><tr><td colspan="9">No model results yet.</td></tr></tbody></table></div>
</div>
<div id="replayModePanel"><div class="status"><span><b>●</b> <span id="datasetStatus">Awaiting dataset</span></span><span><b>▱</b> 9 features required</span><span><b>⬡</b> <span id="modelsStatus">E1–E5: {{ $bundleReady ? 'bundle detected' : 'bundle missing' }}</span></span></div><div class="stats"><div class="stat"><span>Replayed</span><strong id="replayed">0</strong></div><div class="stat"><span>E5 Normal</span><strong id="normalCount">0</strong></div><div class="stat"><span>E5 Attack</span><strong id="attackCount">0</strong></div><div class="stat"><span>E1/E5 Disagreements</span><strong id="disagreeCount">0</strong></div></div><div class="controls"><button id="startBtn" class="btn primary" disabled>▶ Start Replay</button><button id="pauseBtn" class="btn" disabled>Ⅱ Pause</button><button id="resetBtn" class="btn" disabled>↻ Reset</button><label>Records/sec: <select id="speed"><option>1</option><option selected>5</option><option>10</option><option>25</option><option>50</option></select></label><span>Progress:</span><div class="progress"><div id="progressFill"></div></div><strong id="progressText">0 / 0</strong></div><div class="two"><div><div class="panel"><h2>Network Flow Predictions</h2><div class="tablewrap"><table><thead><tr><th>Row</th><th>E1</th><th>E5</th><th>Actual</th></tr></thead><tbody id="flowRows"><tr><td colspan="4" class="empty">Upload and analyse a dataset to begin.</td></tr></tbody></table></div></div><div class="panel" style="margin-top:12px"><h2 id="recordTitle">Model Predictions for Selected Record</h2><div class="tablewrap"><table><thead><tr><th>E1</th><th>E2</th><th>E3</th><th>E4</th><th>E5</th></tr></thead><tbody id="modelRow"><tr><td colspan="5" class="empty">No record selected.</td></tr></tbody></table></div></div></div><div class="panel"><h2 id="featureTitle">Features Examined</h2><div class="tablewrap"><table><thead><tr><th>Feature</th><th>Observed</th><th>Model Input (imputed)</th></tr></thead><tbody id="featureRows"><tr><td colspan="3" class="empty">No record selected.</td></tr></tbody></table></div><div class="orange">Hybrid input: 9 features + continuous IF score</div><div class="score" id="scoreText">E5 continuous IF score: —</div></div></div><div class="panel"><h2>Ablation Study</h2><div class="two" style="margin-bottom:0"><div class="tablewrap"><table><thead><tr><th>Experiment</th><th>Configuration</th><th>Training SMOTE</th></tr></thead><tbody><tr><td>E1</td><td>IF reference baseline</td><td>No</td></tr><tr><td>E2</td><td>RBF-SVM</td><td>No</td></tr><tr><td>E3</td><td>RBF-SVM</td><td>Yes</td></tr><tr><td>E4</td><td>IF–RBF-SVM</td><td>No</td></tr><tr><td>E5</td><td>IF–RBF-SVM</td><td>Yes</td></tr></tbody></table></div><div style="display:flex;flex-direction:column;gap:12px;justify-content:center"><button class="btn primary" data-goto="evaluation">▥ Open Evaluation</button><button class="btn" id="exportBtn" disabled>↓ Export Run JSON</button></div></div></div><p class="footer">SMOTE is used during training only. Displayed predictions are computed from the uploaded CSV, not illustrative values. Replay preview is limited to the first 500 records; all uploaded rows are evaluated.</p></div></section>
<section id="evaluation" class="section"><div class="panel"><h2>Model Evaluation</h2><p class="muted" id="evaluationIntro">Run a labelled CSV to calculate accuracy, precision, recall and other metrics.</p><div class="tablewrap"><table><thead><tr><th>Model</th><th>Accuracy</th><th>Precision</th><th>Recall</th><th>F1</th><th>F0.5</th><th>MCC</th><th>ROC-AUC</th><th>PR-AUC</th><th>Inference (s)</th></tr></thead><tbody id="metricsRows"><tr><td colspan="10" class="empty">No results.</td></tr></tbody></table></div></div></section>
<section id="ablation" class="section"><div class="panel"><h2>Ablation Study (E1–E5)</h2><p>The experiment configurations differ by IF-score augmentation and training-only SMOTE. The same uploaded records are evaluated by each available trained model.</p><div id="ablationMetrics" class="grid4"></div><div id="mcnemar" class="notice hidden"></div></div></section>
</main></div><script>
(()=>{'use strict';const $=id=>document.getElementById(id);const switchMode=live=>{$('liveModePanel').classList.toggle('hidden-mode',!live);$('replayModePanel').classList.toggle('hidden-mode',live);$('liveModeBtn').setAttribute('aria-pressed',String(live));$('replayModeBtn').setAttribute('aria-pressed',String(!live));$('pageTitle').textContent=live?'Live Network Capture Setup':'Recorded Network Traffic Simulation';$('sourceSubtitle').textContent=live?'Local capture integration • Not connected':'UNSW-NB15 dataset replay • Not live network capture';$('modeTag').textContent=live?'LIVE CAPTURE • SETUP REQUIRED':'DATASET REPLAY • REAL INFERENCE'};$('liveModeBtn').onclick=()=>{switchMode(true)};$('replayModeBtn').onclick=()=>switchMode(false);$('returnReplayBtn').onclick=()=>switchMode(false);const features=['sttl','ct_state_ttl','dload','rate','dmean','dttl','ackdat','sload','sbytes'];let result=null,preview=[],shown=0,selected=-1,timer=null,playing=false;const escapeHTML=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=v=>v==null?'—':typeof v==='number'?Number(v.toFixed(5)).toLocaleString():escapeHTML(v);const label=v=>v==null?'<span class="pill unknown">—</span>':`<span class="pill ${Number(v)===1?'attack':'normal'}">${Number(v)===1?'Attack':'Normal'}</span>`;const set=id=>{document.querySelectorAll('.section').forEach(e=>e.classList.toggle('active',e.id===id));document.querySelectorAll('.nav').forEach(e=>e.classList.toggle('active',e.dataset.page===id));$('pageTitle').textContent=({overview:'Dashboard Overview',dataset:'Dataset & Validation',simulation:'Recorded Network Traffic Simulation',evaluation:'Model Evaluation',ablation:'Ablation Study'})[id]};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>set(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>set(b.dataset.goto));$('fileInput').onchange=()=>$('uploadState').textContent=Array.from($('fileInput').files).map(f=>f.name).join(', ')||'No file selected';
async function analyse(){const files=Array.from($('fileInput').files);if(!files.length){$('uploadState').textContent='Select a CSV first.';return}stop();$('analyseBtn').disabled=true;$('uploadState').textContent='Analysing with trained models…';$('validationResult').classList.add('hidden');try{const body=new FormData();files.forEach(f=>body.append('files[]',f));const response=await fetch(@json(route('analysis.analyse')),{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body});const data=await response.json();if(!response.ok)throw Error(data.message||JSON.stringify(data.errors||data));const valid=(data.results||[]).filter(r=>r.ok);if(!valid.length)throw Error((data.results||[]).map(r=>r.error).filter(Boolean).join('; ')||'No valid results.');result=valid[0];preview=result.preview||[];shown=0;selected=-1;$('datasetStatus').textContent='Dataset validated';$('modelsStatus').textContent='E1–E5 results ready';$('uploadState').textContent=`Analysed ${valid.length} file(s), ${result.rows} rows. ${preview.length} replayable preview records.`;$('validationResult').className='notice';$('validationResult').textContent=`Validated ${result.rows} records. ${result.labelled?'Labels available for metrics.':'No labels: classification metrics unavailable.'} ${result.provenance||''}`;$('overviewStatus').textContent=$('uploadState').textContent;['startBtn','resetBtn','exportBtn'].forEach(id=>$(id).disabled=!preview.length);$('pauseBtn').disabled=true;render();renderMetrics();enableDemo();set('simulation')}catch(e){$('uploadState').textContent='Analysis failed';$('validationResult').className='notice error';$('validationResult').textContent=e.message}finally{$('analyseBtn').disabled=false}}
$('analyseBtn').onclick=analyse;
function stop(){playing=false;if(timer!==null){clearInterval(timer);timer=null}$('pauseBtn').disabled=true;$('startBtn').textContent='▶ Start Replay'}
function tick(){if(shown>=preview.length){stop();return}shown++;selected=shown-1;render();if(shown>=preview.length)stop()}
$('startBtn').onclick=()=>{if(!preview.length)return;if(shown>=preview.length){shown=0;selected=-1}stop();playing=true;$('pauseBtn').disabled=false;$('startBtn').textContent='▶ Playing';tick();if(playing)timer=setInterval(tick,1000/Number($('speed').value))};$('pauseBtn').onclick=()=>{stop();$('startBtn').textContent='▶ Resume Replay'};$('resetBtn').onclick=()=>{stop();shown=0;selected=-1;render()};$('speed').onchange=()=>{if(playing){clearInterval(timer);timer=setInterval(tick,1000/Number($('speed').value))}};
function render(){const rows=preview.slice(0,shown);$('replayed').textContent=shown;$('normalCount').textContent=rows.filter(r=>r.experiments?.E5===0).length;$('attackCount').textContent=rows.filter(r=>r.experiments?.E5===1).length;$('disagreeCount').textContent=rows.filter(r=>r.experiments?.E1!==r.experiments?.E5).length;$('progressText').textContent=`${shown} / ${preview.length}`;$('progressFill').style.width=preview.length?`${shown/preview.length*100}%`:'0%';$('flowRows').innerHTML=rows.length?rows.slice(-30).map((r,i)=>`<tr data-row="${shown-Math.min(shown,30)+i}" class="${selected===shown-Math.min(shown,30)+i?'selected':''}"><td>${r.row}</td><td>${label(r.experiments?.E1)}</td><td>${label(r.experiments?.E5)}</td><td>${label(r.label)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">Press Start Replay to display predictions.</td></tr>';document.querySelectorAll('#flowRows tr[data-row]').forEach(tr=>tr.onclick=()=>{selected=Number(tr.dataset.row);render()});const r=preview[selected];$('recordTitle').textContent=r?`Model Predictions for Record ${r.row}`:'Model Predictions for Selected Record';$('featureTitle').textContent=r?`Features Examined — Record ${r.row}`:'Features Examined';$('modelRow').innerHTML=r?`<tr>${['E1','E2','E3','E4','E5'].map(k=>`<td>${label(r.experiments?.[k])}</td>`).join('')}</tr>`:'<tr><td colspan="5" class="empty">No record selected.</td></tr>';$('featureRows').innerHTML=r?features.map(f=>`<tr><td>${f}</td><td>${fmt(r.features?.[f])}</td><td>${fmt(r.cleaned?.[f])}${(r.imputed||[]).includes(f)?' *':''}</td></tr>`).join(''):'<tr><td colspan="3" class="empty">No record selected.</td></tr>';$('scoreText').textContent=r?`E5 continuous IF score: ${fmt(r.if_score)} • Not a probability`:'E5 continuous IF score: —'}
function demoPick(actual){const candidates=preview.filter(r=>r.label===actual);return candidates.find(r=>r.experiments?.E5===actual)||candidates[0]||null}
function demoDisplay(which){const samples=which==='both'?[demoPick(0),demoPick(1)]:[demoPick(which==='attack'?1:0)];const chosen=samples.filter(Boolean);$('demoRows').innerHTML=chosen.length?chosen.map(r=>`<tr><td>${r.row}</td><td>${label(r.label)}</td>${['E1','E2','E3','E4','E5'].map(k=>`<td>${label(r.experiments?.[k])}</td>`).join('')}<td>${fmt(r.if_score)}</td><td>${r.experiments?.E5===r.label?'Correct':'Misclassified'}</td></tr>`).join(''):'<tr><td colspan="9">No record with this ground-truth label in the uploaded data.</td></tr>';$('demoNotice').textContent=chosen.length?'Real predictions from the trained bundle; rows '+chosen.map(r=>r.row).join(' and ')+'. A ground-truth Attack label does not guarantee an Attack prediction.':'No matching labeled records available.'}
$('demoNormalBtn').onclick=()=>demoDisplay('normal');$('demoAttackBtn').onclick=()=>demoDisplay('attack');$('demoCompareBtn').onclick=()=>demoDisplay('both');
function enableDemo(){const labelled=!!result?.labelled;const has0=labelled&&preview.some(r=>r.label===0),has1=labelled&&preview.some(r=>r.label===1);$('demoNormalBtn').disabled=!has0;$('demoAttackBtn').disabled=!has1;$('demoCompareBtn').disabled=!(has0&&has1);$('demoNotice').textContent=!labelled?'Upload a CSV with a binary label column (0/1) to compare predictions.':!has0||!has1?'Only one ground-truth class was found; upload both classes for a comparison.':'Ready: both classes available. These are model outputs, not hardcoded classifications.';if(has0&&has1)demoDisplay('both')}
function renderMetrics(){if(!result)return;const cs=result.configurations||{};$('evaluationIntro').textContent=result.labelled?'Metrics calculated using labels in the uploaded dataset. This does not prove the upload is the official held-out test partition.':'The uploaded CSV has no label column; accuracy and other supervised metrics cannot be computed.';$('metricsRows').innerHTML=['E1','E2','E3','E4','E5'].map(k=>{const v=cs[k]||{};return `<tr><td><b>${k}</b></td>${['accuracy','precision','recall','f1','f0_5','mcc','roc_auc','pr_auc','inference_seconds'].map(x=>`<td>${fmt(v[x])}</td>`).join('')}</tr>`}).join('');$('ablationMetrics').innerHTML=['E1','E2','E3','E4','E5'].map(k=>`<div class="metric"><b>${k}</b><strong>${result.labelled?fmt(cs[k]?.f1):'—'}</strong><span class="small">${result.labelled?'F1 score':'No ground-truth labels'}</span><p class="small">${fmt(cs[k]?.attacks)} attacks / ${fmt(cs[k]?.normal)} normal</p></div>`).join('');if(result.mcnemar){$('mcnemar').classList.remove('hidden');$('mcnemar').textContent=`McNemar ${result.mcnemar.comparison}: p = ${fmt(result.mcnemar.pvalue)} (${result.mcnemar.method})`}else $('mcnemar').classList.add('hidden')}
$('exportBtn').onclick=()=>{if(!result)return;const blob=new Blob([JSON.stringify({exported_at:new Date().toISOString(),source:'LCC dataset replay',result},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='lcc-e1-e5-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render()})();
</script>
<script>
(()=>{
  const liveApi=window.LIVE_CAPTURE_API_URL||'http://127.0.0.1:8010';
  const panel=document.querySelector('#liveModePanel .live-layout .panel');
  if(!panel)return;
  const intro=panel.querySelector('h2').nextElementSibling;
  intro.textContent='Capture authorized traffic from a local interface, aggregate it into short-lived flows, and run the same E1–E5 bundle used by CSV replay.';
  const steps=panel.querySelectorAll('.live-step p');
  if(steps[0])steps[0].textContent='Install Npcap and the Python dependencies from capture_api/requirements.txt on the capture computer.';
  if(steps[1])steps[1].textContent='The local service aggregates packets into flows and calculates the nine model input columns.';
  if(steps[2])steps[2].textContent='Start the local capture service, choose an interface if needed, then use Start Capture below.';
  const controls=document.createElement('div');
  controls.className='panel';
  controls.style.cssText='margin:14px 0;border:2px solid #c7d9e8;background:#f8fbfe';
  controls.innerHTML='<h2 style="margin-top:0">Live Capture Controls</h2><div class="upload"><label for="captureInterface">Interface (optional)</label><input id="captureInterface" placeholder="default interface" maxlength="128"><button id="startCaptureBtn" class="btn primary" type="button">▶ Start Capture</button><button id="stopCaptureBtn" class="btn" type="button" disabled>■ Stop Capture</button></div><p id="captureStatusText" class="muted small" aria-live="polite">Checking local capture service…</p><p id="captureFeatureNote" class="small muted"></p><div class="tablewrap"><table><thead><tr><th>Flow</th><th>E1</th><th>E5</th><th>IF score</th><th>Packets</th></tr></thead><tbody id="liveRows"><tr><td colspan="5" class="empty">No live flows yet.</td></tr></tbody></table></div>';
  panel.insertBefore(controls,panel.querySelector('.live-step'));
  const start=document.querySelector('#startCaptureBtn'),stop=document.querySelector('#stopCaptureBtn'),status=document.querySelector('#captureStatusText'),note=document.querySelector('#captureFeatureNote'),rows=document.querySelector('#liveRows'),iface=document.querySelector('#captureInterface');
  let poll=null;
  const esc=value=>String(value??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const outcome=value=>`<span class="pill ${Number(value)===1?'attack':'normal'}">${Number(value)===1?'Attack':'Normal'}</span>`;
  const setState=running=>{start.disabled=running;stop.disabled=!running;};
  function render(data){
    setState(!!data.running);
    const service=data.last_error?`Capture error: ${data.last_error}`:data.running?`Capturing on ${data.interface||'default interface'} · ${data.packets} packets · ${data.flows} flows`:`Capture service ready · ${data.packets||0} packets in the last session`;
    status.textContent=service;
    note.textContent=data.feature_mode||'Live flow features are approximate and have no ground-truth labels.';
    const items=(data.predictions||[]).slice(-20).reverse();
    rows.innerHTML=items.length?items.map((r,i)=>`<tr><td>${esc(r.row||items.length-i)}</td><td>${outcome(r.experiments?.E1)}</td><td>${outcome(r.experiments?.E5)}</td><td>${esc(Number(r.if_score??0).toFixed(5))}</td><td>${esc(r.live_flow?.packets||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No completed live flows yet.</td></tr>';
  }
  async function request(path,options={}){
    const response=await fetch(`${liveApi}${path}`,{headers:{'Content-Type':'application/json'},...options});
    const data=await response.json().catch(()=>({detail:'Capture service returned a non-JSON response.'}));
    if(!response.ok)throw new Error(data.detail||'Capture service request failed.');
    return data;
  }
  async function refresh(){try{render(await request('/capture/status'))}catch(error){setState(false);status.textContent=`Live service unavailable: ${error.message}`;note.textContent='Start capture_api/capture_service.py on localhost:8010, then try again.'}}
  start.onclick=async()=>{try{render(await request('/capture/start',{method:'POST',body:JSON.stringify({interface:iface.value.trim()})}));clearInterval(poll);poll=setInterval(refresh,2000)}catch(error){status.textContent=`Unable to start capture: ${error.message}`}};
  stop.onclick=async()=>{try{clearInterval(poll);render(await request('/capture/stop',{method:'POST'}))}catch(error){status.textContent=`Unable to stop capture: ${error.message}`}};
  document.querySelector('#liveModeBtn').addEventListener('click',refresh);
  document.querySelector('#returnReplayBtn').addEventListener('click',()=>{clearInterval(poll)});
  refresh();
})();
</script></body></html>
